export interface FAQItem {
  question: string;
  answer: string;
}

export const runningFaqs: Record<string, FAQItem[]> = {
  'pace-calculator': [
    { question: 'How do you calculate running pace manually?', answer: 'Divide your total running time by the total distance covered. If you run 5 kilometers in 25 minutes, divide 25 by 5 to get 5:00 per kilometer. For miles, run 3 miles in 27 minutes and you get 9:00 per mile. The formula is pace = total time / distance, expressed in minutes per mile or per kilometer. To convert the result to speed, divide 60 by your pace in minutes: a 5:00/km pace equals 60 / 5 = 12 km/h. This calculator does all the division and unit conversions for you automatically.' },
    { question: 'What is the difference between speed and pace?', answer: 'Speed measures distance covered per unit of time, such as 10 km/h or 6.2 mph. Pace is the inverse: the time it takes to cover one unit of distance, written as minutes per kilometer or per mile. Runners use pace because it maps directly to splits and race planning. To convert pace into speed, divide 60 by the pace in minutes: 5:00/km becomes 60 / 5 = 12 km/h, and 9:00/mile becomes 60 / 9 = 6.7 mph. Use speed for treadmill settings and pace for road races.' },
    { question: 'What pace do I need for a sub-30 minute 5K?', answer: 'To finish a 5K in under 30 minutes, hold an average pace of 6:00 per kilometer, which equals 9:39 per mile. Your cumulative kilometer splits should be about 6:00, 12:00, 18:00, 24:00, and then the final kilometer in under 6 minutes. A 30-minute 5K sits right at the middle of recreational times, so it is an achievable target for many beginners after 8-12 weeks of consistent training. Enter 30:00 as your time and 5 km as the distance to see per-mile and per-km splits.' },
    { question: 'How does hot weather affect my running pace?', answer: 'Heat slows you down because your body diverts blood to the skin to cool off, leaving less for working muscles. As a general rule, pace slows about 1-3% for every 5°C above roughly 15°C. That means on a 25°C day you may run 30-60 seconds per mile slower than on a cool morning at the same effort. Above 30°C, expect even bigger slowdowns and a higher risk of dehydration. Use perceived effort or heart rate rather than pace on hot days, and adjust goal times in the calculator.' },
    { question: 'How do I calculate my average pace if my speed changed during the run?', answer: 'Your average pace is simply total elapsed time divided by total distance, regardless of how the speed varied. If you jogged the first mile at 10:00, then ran the next two miles at 8:00, your total time is 26:00 over 3 miles, giving an average pace of 8:40 per mile. GPS watches show the same number when they report \'average pace\' over the whole activity. Do not average your split paces arithmetically, because that ignores the different time spent at each speed.' },
    { question: 'What is the difference between average pace and current pace on a running watch?', answer: 'Average pace is your total time divided by total distance for the whole run or lap, so it barely moves and reflects overall effort. Current pace is a rolling estimate of how fast you are running right now, usually averaged over the last few seconds or a short distance window. Current pace jumps around on hills, turns, and in GPS tunnels, while average pace stays stable. For steady effort, watch average pace or lap pace; for surges and intervals, use current pace as a guide only.' },
    { question: 'What incline should I set on a treadmill to match outdoor pace?', answer: 'The classic rule, based on a 1996 study by Jones and Doust, is to set the treadmill to 1% incline to reproduce the energy cost of running outdoors on flat ground. This is validated for paces between about 9:11 and 5:22 per mile (5:42 to 3:20 per km). For slower easy running below 9:11/mile, 0.5% is closer, and for very fast running under 5:22/mile, about 2% is a better match. Below these speeds the belt and lack of air resistance make 0% feel noticeably easier than the road.' },
  ],

  'running-pace-calculator': [
    { question: 'How do I find my running pace per mile and per kilometer?', answer: 'Enter your total distance and time into the calculator. It divides the time by the distance to give your minutes per kilometer, then multiplies that pace by 1.609344 to show the equivalent minutes per mile. For example, running 5 km in 25 minutes gives 5:00/km, which converts to 8:03/mile. The reverse works by dividing mile pace by 1.609344. Both numbers describe the same effort, so use whichever unit matches your race course or training app.' },
    { question: 'Why does my running pace vary from day to day?', answer: 'Pace is influenced by sleep, hydration, heat, humidity, wind, hills, terrain, and accumulated fatigue, even when your fitness is unchanged. Heat above 15°C can slow you by 1-3% for every 5°C increase. Sleep debt of just a few hours can add 20-40 seconds per mile. Hormonal cycles, stress, and caffeine also shift pace. If your pace drops 30-60 seconds per mile for several consecutive days, you are probably undertrained or under-recovered rather than losing fitness.' },
    { question: 'How much does running pace slow with age?', answer: 'Research on masters runners shows performance declines roughly 7-10% per decade after peak performance in the mid-to-late 20s. In practical terms, that works out to about 20-30 seconds per mile slower per decade for the same effort. The decline is gradual through your 40s, then accelerates after 55, driven by drops in VO2max and muscle mass. Consistent training, speed work, and strength work significantly slow this decline, so many well-trained masters runners outperform untrained runners decades younger.' },
    { question: 'What pace should a beginner run to build an aerobic base?', answer: 'A beginner should run at a conversational pace where they can speak in full sentences, roughly 60-120 seconds per mile slower than their current 5K race pace. For a 35-minute 5K runner, that means easy runs around 11:30-12:30 per mile. If you cannot talk, slow down. Walk breaks are completely fine when first building a base. The goal is time on feet at low effort, not speed, because easy miles develop the aerobic system, capillaries, and tendon strength that faster training later depends on.' },
    { question: 'What is a negative split and why should I try it?', answer: 'A negative split means running the second half of a race faster than the first half. Most personal bests and world records are set with negative or even splits, because starting slightly slower preserves glycogen and prevents early lactate accumulation. For a half marathon, aim to run the first half 30-90 seconds slower than the second; for a full marathon, 1-3 minutes slower. Practicing this in training with progression runs teaches your body to accelerate on tired legs.' },
    { question: 'How do I convert my running pace to speed in km/h or mph?', answer: 'Divide 60 by your pace expressed in decimal minutes. If your pace is 6:00 per kilometer, that is 6.0 minutes, so 60 / 6 = 10 km/h. For 9:00 per mile, 60 / 9 = 6.7 mph. Convert between the two by multiplying km/h by 0.6214 to get mph. Treadmills display speed, while GPS watches usually show pace, so this conversion lets you match an outdoor pace to a machine setting or compare effort across platforms.' },
    { question: 'How accurate are GPS watch pace readings?', answer: 'Most GPS watches are accurate to within 1-3% on open roads with clear sky, but signal drift, tall buildings, tree cover, and tight turns introduce error. Running on a 400m track, watch distance can come up short or long by 2-5%. For race-critical work use a calibrated footpod, a stryd-style pod, or lap timing at known marks. On a treadmill, trust the belt distance over the watch, since there is no GPS signal and the watch relies on accelerometer estimates.' },
  ],

  'mile-pace-calculator': [
    { question: 'How do I convert minutes per mile to minutes per kilometer?', answer: 'Convert your mile pace to decimal minutes, then divide by 1.609344. For an 8:00 mile, that is 8.0 minutes; 8.0 divided by 1.609344 equals 4.97 minutes, which is about 4:58 per kilometer. Multiply by 1.609344 to go the other way: a 5:00/km pace is an 8:03 mile. Use this conversion when you race internationally or train on metric tracks, and to compare your mile splits with kilometer-based pace zones.' },
    { question: 'What is a fast mile pace for adults?', answer: 'For recreational runners, a mile under 7:00 (4:21/km) is considered fast, and under 6:00 is competitive. The average recreational mile time is closer to 9:00-11:00 depending on age. Elite men run miles under 3:55 and elite women under 4:20. The world record is 3:43.13 by Hicham El Guerrouj (1999), with the women\'s record at 4:07.64 by Faith Kipyegon (2023). Your mile pace also predicts longer races via Riegel\'s formula.' },
    { question: 'What is a good mile time for a beginner?', answer: 'Most beginners run their first continuous mile in 10-12 minutes, and that is a perfectly good starting point. A reasonable first goal is to finish a mile without walking, then gradually bring the time down. With 8-12 weeks of running 3-4 times per week, most new runners can improve to 9:00 or under. Use the run-walk method if needed: run 1 minute, walk 1 minute, then lengthen the run segments as fitness builds before testing an all-out mile.' },
    { question: 'How do I pace a track mile race?', answer: 'The track mile is 4 laps, so aim for even 400m splits. For a 6:00 mile, each lap should be 90 seconds. For a 7:00 mile, each lap is 1:45. Start each lap on time, resist surging in lap 1, and save a small kick for the final 200m. Even pacing beats going out fast because the last lap is always harder. Practice hitting your target 400m split in training, since a 3-4 second error per lap changes your finish by 12-16 seconds.' },
    { question: 'How many meters is a mile and is 1600m the same?', answer: 'A full mile is exactly 1,609.34 meters, or 5,280 feet. The \'metric mile\' run on tracks is 1,600 meters, which is 9.34 meters shorter, about a 3-4 second difference for most runners. In a 400m track, a true mile is 4 full laps plus 9.34 meters. When comparing times, note whether the race was a full mile or a 1600m, because the shorter distance flatters your pace slightly.' },
    { question: 'How can I predict my 5K time from a mile time?', answer: 'Use Riegel\'s formula: T2 = T1 x (D2/D1)^1.06. For a mile to 5K conversion, the factor is about 3.33, so a 6:00 mile predicts roughly a 19:50-20:00 5K, and a 7:00 mile predicts about a 23:15 5K. The prediction assumes even pacing and similar endurance training at both distances. A mile is more speed-oriented than a 5K, so runners with more mileage may outperform the prediction.' },
    { question: 'What pace per kilometer is a 6:00 mile?', answer: 'A 6:00 mile equals 10 mph, which is 16.09 km/h. Converted to pace, that is 3:44 per kilometer (6 minutes divided by 1.609344 = 3.73 minutes). Knowing this helps you match track workouts, treadmill settings, and metric race splits. A 3:44/km effort is roughly 5K race pace for a sub-20 minute 5K runner, so a 6:00 mile and a 19:50 5K represent very similar aerobic fitness.' },
  ],

  '5k-pace-calculator': [
    { question: 'What is a good 5K finish time for beginners?', answer: 'For most beginners who follow a program like Couch to 5K, finishing between 30 and 40 minutes is typical and excellent. That is an average pace of 6:00-8:00 per kilometer, or 9:39-12:52 per mile. Men tend to finish toward the faster end and women toward the slower end, but individual variation is huge. The goal for your first 5K should be completion, not a specific time. After a few months of consistent running, most beginners drop 3-5 minutes.' },
    { question: 'What pace is needed to run a sub-20 minute 5K?', answer: 'To break 20 minutes in a 5K, you must hold a steady pace of 3:59 per kilometer, which is 6:26 per mile. Your kilometer splits should be about 3:59, 7:58, 11:57, 15:56, and the last kilometer slightly faster to finish under 20:00. A sub-20 5K puts you in roughly the top 10-15% of finishers and demands both strong aerobic fitness and structured training including intervals and threshold work.' },
    { question: 'What 5K pace do I need for a sub-30 minute finish?', answer: 'A sub-30 minute 5K requires an average pace of exactly 6:00 per kilometer, or 9:39 per mile. Your kilometer splits should read 6:00, 12:00, 18:00, and 24:00 at the 4km mark, leaving the final kilometer to finish under 30. This is a very common first-time goal: it sits right at the middle of recreational times and is achievable for most people within a few months of regular training with one or two speed sessions per week.' },
    { question: 'How should I split a 5K to run an even race?', answer: 'For even pacing, your first kilometer should match your target pace almost exactly, not be faster. For a 25-minute 5K (5:00/km), hit 5:00 at the 1km marker, 10:00 at 2km, 15:00 at 3km, and 20:00 at 4km. Going out too fast in the first mile floods your legs with lactate and costs you far more time later. Many runners find a small negative split works best: the second half 5-10 seconds per km faster than the first.' },
    { question: 'How do I convert my 5K time into a predicted 10K time?', answer: 'Use Riegel\'s formula, T2 = T1 x (D2/D1)^1.06. Going from 5K to 10K, the factor is about 2.086, so a 25:00 5K predicts a 52:10 10K and a 20:00 5K predicts about 41:45. The prediction assumes you have done the training volume to sustain the extra distance. Because the 10K requires more endurance, runners who mostly train for 5K speed will come out slower than the prediction, while higher-mileage runners may beat it.' },
    { question: 'How much faster is 5K race pace than easy training pace?', answer: 'Your 5K race pace is typically 1.5 to 2.5 minutes per mile (60-120 seconds per kilometer) faster than your easy training pace. A runner with a 25:00 5K (5:00/km race pace) should do easy runs around 6:00-6:30/km. This big gap is normal and healthy. Easy miles build the aerobic base that makes 5K pace feel sustainable, so never try to force all your training runs closer to race pace, which is the most common beginner mistake.' },
    { question: 'What is the average 5K time by age?', answer: 'Across all ages and genders, the average 5K is about 24-32 minutes. For men, averages by age group are roughly 25:15 for 20-29, 26:45 for 30-39, and 28:20 for 40-49. Women average about 31:30 for 20-29, 32:45 for 30-39, and 33:30 for 40-49. Performance peaks in the 25-34 range and declines about 7-10% per decade after that. Compare yourself to your own age group, not to overall averages.' },
  ],

  '10k-pace-calculator': [
    { question: 'What is the average 10K running pace?', answer: 'The average 10K pace for recreational runners is between 9:00 and 11:00 per mile (5:36 to 6:50 per kilometer), which produces a finish time of 55 to 70 minutes. Across a broad population, the median 10K finish is close to 60 minutes, or 6:00/km. Men average slightly faster than women, and times slow roughly 7-10% per decade after age 35. These averages include everyone from casual fun-runners to competitive age-groupers.' },
    { question: 'What pace is required to run a 10K under 50 minutes?', answer: 'To finish a 10K under 50 minutes, hold an average pace of 5:00 per kilometer, which equals 8:03 per mile. Your 5K split should come at roughly 25:00, keeping the effort even across both halves. Set your 2K splits at 10:00 to stay on track. A sub-50 10K is a solid intermediate goal and typically requires a consistent training base of 20-30 miles per week with one tempo or interval session.' },
    { question: 'What pace do I need to break 40 minutes in the 10K?', answer: 'A sub-40 minute 10K requires a steady average pace of 4:00 per kilometer, or 6:26 per mile. You should pass 5K in about 20 minutes and each kilometer at 4:00 to stay on pace. This is a competitive time that places you in the top 10-15% of most 10K fields. It demands structured training with weekly threshold runs and intervals, plus enough easy mileage to sustain the pace for the full 6.2 miles.' },
    { question: 'What pace for a sub-45 minute 10K?', answer: 'To run a 10K in under 45 minutes, average 4:30 per kilometer, or 7:15 per mile. Your 5K split lands around 22:30, and each kilometer should take about 4:30. This is roughly 10K pace for runners who can also go under 21:30 in a 5K. Sub-45 is a popular intermediate goal and usually requires 8-12 weeks of consistent training with one quality session per week plus easy base miles.' },
    { question: 'How does 10K pace compare to half marathon pace?', answer: 'Half marathon pace is roughly 10-15 seconds per kilometer (15-25 seconds per mile) slower than 10K pace for the same runner. If your 10K pace is 5:00/km, your half marathon pace will be around 5:10-5:15/km, giving a finish of about 1:49-1:51. The difference exists because the half marathon is more than twice the distance, so you must run comfortably below your threshold rather than at the edge of it.' },
    { question: 'How many miles is a 10K race?', answer: 'A 10K is exactly 10 kilometers, which equals 6.2137 miles, usually rounded to 6.2 miles. It is one of the most popular road race distances because it is long enough to be a real endurance test yet short enough for strong pacing. A 60-minute 10K means you averaged 9:39 per mile, and a 50-minute 10K is 8:03 per mile. The 10K bridges the gap between the 5K and the half marathon.' },
    { question: 'What splits should I hit in a 10K for even pacing?', answer: 'Plan your splits in 2K blocks to make pacing simple. For a 50-minute 10K, hit 10:00 at 2K, 20:00 at 4K, 30:00 at 6K, and 40:00 at 8K, then close the final 2K in under 10:00. For a 45-minute target, use 9:00 blocks; for 40 minutes, use 8:00 blocks. Running the first 2-3 km slightly under goal pace prevents the late-race fade that comes from going out too fast.' },
  ],

  'half-marathon-pace-calculator': [
    { question: 'What is a respectable half marathon time and pace?', answer: 'For recreational runners, finishing a half marathon (13.1 miles or 21.0975 km) under 2 hours is a hugely popular benchmark, requiring a steady pace of 9:09 per mile (5:41 per kilometer). The median half marathon finish is about 2:15 overall, with men around 1:59:48 and women around 2:24. Sub-1:45 (8:00/mile) is considered strong, and sub-1:30 (6:50/mile) is elite-amateur territory. Compare yourself to your age group, not the field.' },
    { question: 'What is the average half marathon time for beginners?', answer: 'Beginner runners typically finish their first half marathon in 2 hours 15 minutes to 2 hours 45 minutes, an average pace of 10:18 to 12:35 per mile (6:24 to 7:49 per kilometer). Planned walk breaks are completely normal and acceptable for first-timers. With a 12-16 week plan peaking at 20-30 miles per week and one long run building from 6 to 13 miles, most people can complete the distance comfortably.' },
    { question: 'What pace do I need for a sub-2:00 half marathon?', answer: 'To break 2 hours in a half marathon, hold an average pace of 5:41 per kilometer, which equals 9:09 per mile. Your checkpoints should be about 28:27 at 5K, 56:54 at 10K, and 1:25:21 at 15K, leaving the final 6.1 km in under 34:39. A sub-2:00 half is the most common intermediate goal and requires a solid base of 25-30 miles per week plus one long run and one quality session each week.' },
    { question: 'What pace for a sub-1:45 half marathon?', answer: 'A sub-1:45 half marathon means running 4:58 per kilometer, or 8:00 per mile, for all 13.1 miles. Your 5K splits should be about 24:52 each, with the halfway mark passed around 52:30. This is a strong recreational-to-competitive time that typically needs 30-40 miles per week with weekly tempo and interval work. Practicing a slightly negative split helps: aim for 5:00/km in the first half and pick up to 4:55 in the second.' },
    { question: 'What pace for a sub-1:30 half marathon?', answer: 'To run a half marathon under 1:30, average 4:15 per kilometer, or 6:50 per mile. Your halfway split must come in about 45:00, and each 5K block should take roughly 21:15. A sub-1:30 half places you near the top of most age groups and demands consistent mileage around 40-50 miles per week with structured threshold workouts. It roughly equates to a 41-42 minute 10K using Riegel\'s formula.' },
    { question: 'How does half marathon pace differ from 10K pace?', answer: 'Half marathon pace is typically 10-15 seconds per kilometer (15-25 seconds per mile) slower than your 10K pace. A runner who races 10K at 4:45/km should target roughly 4:55-5:00/km for a half marathon, finishing around 1:45. The half marathon is run just below lactate threshold, while a 10K sits at or slightly above it. Holding a pace that feels \'comfortably hard\' rather than \'race effort\' is the key difference.' },
    { question: 'What pace should my long runs be during half marathon training?', answer: 'Your half marathon long runs should be 30-90 seconds per mile (about 20-60 seconds per kilometer) slower than your goal half marathon pace. If your goal pace is 9:00/mile, long runs belong around 9:30-10:30/mile at a conversational effort. The point of the long run is time on feet and aerobic endurance, not speed. Save goal-pace running for the last few miles of a long run or dedicated tempo sessions.' },
  ],

  'marathon-pace-calculator': [
    { question: 'What pace is needed to run a sub-4 hour marathon?', answer: 'To run a marathon under 4 hours, hold a steady average pace of 9:09 per mile, or 5:41 per kilometer, across 26.2 miles. Your 5K splits should be about 28:25 each, and you should pass the halfway mark at roughly 2:00:00. This works out to a projected finish of about 3:59:40. Sub-4 is the most popular marathon goal for recreational runners and typically requires a 16-20 week plan peaking at 35-50 miles per week.' },
    { question: 'What pace is required to run a sub-3 hour marathon?', answer: 'A sub-3 hour marathon requires averaging 6:51 per mile (4:16 per kilometer) for the entire 26.2 miles. Your half-marathon split must come in under 1:30:00, and each 5K block should take about 21:22. This is a highly competitive time that places most runners in the top 5% of marathon finishers. It demands 50-70+ miles per week, disciplined threshold training, and flawless race-day pacing and fueling.' },
    { question: 'What pace do I need for a sub-3:30 marathon?', answer: 'A sub-3:30 marathon requires averaging 8:00 per mile, or 4:58 per kilometer, for all 26.2 miles. Your halfway split should be about 1:45:00, and each 5K block takes roughly 24:52. Sub-3:30 is a strong, achievable goal for committed recreational runners, usually demanding 40-55 miles per week with one long run, one tempo run, and one interval session. It also roughly equates to a 1:40 half marathon in most pace tables.' },
    { question: 'What are the Boston Marathon qualifying times for 2026?', answer: 'For the 2026 and 2027 Boston Marathons, men\'s standards are 2:55 for ages 18-34, 3:00 for 35-39, 3:05 for 40-44, 3:15 for 45-49, and 3:20 for 50-54. Women\'s standards are 30 minutes slower in each group: 3:25, 3:30, 3:35, 3:45, and 3:50. Meeting the standard alone does not guarantee entry, because demand exceeds field size. The 2026 cutoff was 4:34 faster than the standard, and recent cutoffs have ranged from 0 to nearly 7 minutes.' },
    { question: 'How much faster should my second half be for a negative split marathon?', answer: 'For most runners, a negative split of 1-3 minutes over the full marathon works well. On a 3:30:00 goal, that looks like a 1:45:30 first half and a 1:44:30 second half, roughly 3 seconds per km faster in the second half. More than 3 minutes usually means you left time on the table early; less than 1 minute is basically even splits, which is still excellent. Even splitting is the safest strategy for a first marathon.' },
    { question: 'What 5K splits do I need for a sub-4 hour marathon?', answer: 'A marathon is 42.195 km, so a sub-4 hour target divides into 8 full 5K blocks plus a final 2.195 km. Each 5K block should take about 28:25, and the last 2.2 km around 12:30. Your checkpoints would be about 56:50 at 10K, 1:25:15 at 15K, and 2:00:00 at the half. Pacing is the biggest factor: even splits with a slightly faster finish beat going out at 27:00 5Ks and fading badly.' },
    { question: 'How fast should my long runs be during marathon training?', answer: 'Most marathon long runs should be 10-20% slower than your goal marathon pace. Pete Pfitzinger\'s guideline is exactly this: for a 5:00/km marathon pace, start long runs at 6:00/km and finish around 5:30/km. Runner\'s World uses the same 10-20% band. Easy long runs build capillaries, mitochondria, and glycogen storage. Reserve marathon-pace running for structured blocks inside the long run, like the final 5-8 miles at goal pace.' },
  ],

  'race-pace-calculator': [
    { question: 'How do I estimate a realistic race pace?', answer: 'Start with a recent time trial or shorter race result. If you raced 5K in 25:00, use Riegel\'s formula, T2 = T1 x (D2/D1)^1.06, to predict equivalent times at longer distances: about 52:10 for 10K and 1:55 for a half marathon. This assumes you have trained adequately for the longer distance. Add a safety margin for your first attempt at any new distance, and consider course hills, heat, and wind before committing to a goal pace.' },
    { question: 'What is Riegel\'s formula for race time prediction?', answer: 'Riegel\'s formula predicts a race time from a known performance: T2 = T1 x (D2/D1)^1.06, where T1 is your known time over distance D1 and T2 is the predicted time over distance D2. The exponent 1.06 accounts for fatigue growing with distance. It is most reliable when the two distances are within about 2-3x of each other: a 10K-to-half prediction is usually within 2-3 minutes for well-trained runners, while predicting a marathon from a 5K is less trustworthy.' },
    { question: 'How do I calculate a pace band for a custom distance like a 50K?', answer: 'First set a realistic goal finish time, either from a recent result using Riegel\'s formula or from a training run at the same terrain. Then divide the goal time by the distance: for a 50K in 6 hours, that is 360 minutes divided by 50 km, giving 7:12 per kilometer (11:36 per mile). Break the route into 5K checkpoints, each worth 36 minutes. Add elevation and aid-station stops, which usually add 1-2% to your total time.' },
    { question: 'How much does heat slow your race pace?', answer: 'Above about 15°C, pace slows roughly 1-3% for every 5°C rise in temperature. At 25°C, expect to be 2-6% slower than your cool-day goal pace; at 30°C that can reach 5-10% slower, especially over 10K and longer. The slowdown is larger for slower runners because they spend more time absorbing heat. Adjust your goal pace accordingly or lower your time target, and base effort on heart rate rather than pace on hot race days.' },
    { question: 'How fast should I run the first mile of a race?', answer: 'The first mile should be your goal pace or slightly slower, never faster. Adrenaline at the start makes most runners run 10-20 seconds per mile faster than planned without noticing. For a goal pace of 8:00/mile, target 8:00-8:15 for the opening mile, then settle in. Data from major marathons shows that runners who go out too fast fade badly and finish slower overall. A slightly conservative start also leaves room for a strong, negative-split finish.' },
    { question: 'How does altitude affect race pace?', answer: 'Above about 1,500 meters (5,000 feet), the reduced oxygen in the air slows your pace significantly. As a rough guide, expect to run about 3-5% slower at 1,500-2,400m, and 8-12% slower above 3,000m, until you are acclimatized. That means a 4:30/km runner may slow to 4:40-4:45/km at altitude. Full acclimatization takes 2-4 weeks. If you race at altitude soon after arriving, adjust your goal pace upward and run by effort.' },
    { question: 'Should I run even splits or negative splits in a race?', answer: 'For races of 10K and longer, negative splits (second half faster than the first) consistently produce the fastest times, with even splits close behind. For a half marathon, run the first half 30-90 seconds slower than the second; for a marathon, aim for 1-3 minutes slower in the first half. Positive splits, where you slow dramatically, are the most common pacing error. At 5K and shorter, go out at goal pace and hold on, since glycogen is not a factor.' },
  ],

  'finish-time-calculator': [
    { question: 'How do you predict a race finish time from pace?', answer: 'Multiply your average pace per unit by the race distance. If your pace is 6:00 per kilometer and you are racing a half marathon (21.0975 km), multiply 6 minutes by 21.0975 to get 126.6 minutes, or 2:06:36. For miles, an 8:00/mile pace over a 10K (6.214 miles) gives 49:43. The calculator performs this multiplication and formats the result into hours, minutes, and seconds while showing cumulative split times at every checkpoint.' },
    { question: 'What is the difference between gun time and chip time?', answer: 'Gun time is measured from the starter\'s signal to the moment you cross the finish line, including any delay before you reach the start mat in a crowded corral. Chip time is your net time, measured from crossing the start mat to crossing the finish mat, so it only counts your actual running. Most race rankings use chip time for age-group awards. Finish-time calculators assume chip time, so enter your net time, never the gun time, when planning goals and splits.' },
    { question: 'How do I predict my marathon time from a 10K result?', answer: 'Apply Riegel\'s formula with your 10K as the reference: T2 = T1 x (42.195/10)^1.06. The factor is about 4.68, so a 45:00 10K predicts a marathon of 45 x 4.68 = 210.6 minutes, or about 3:30:36. A 50:00 10K predicts roughly 3:54. These predictions assume marathon-specific endurance training. Runners who have only trained for 10K speed will finish slower, while those with proper long-run mileage often run close to or faster than the prediction.' },
    { question: 'Why is my actual finish time slower than the calculator\'s prediction?', answer: 'Calculators assume even effort, ideal weather, flat terrain, and adequate fueling. Real-world factors push your time up: heat above 15°C, headwinds, hills, poor hydration, too-fast starts, and under-fueling all slow you down. The 10-15% of time most runners lose to heat and hills is well documented. If your prediction came from a shorter race, a lack of endurance for the longer distance is the usual cause. Use predictions as a baseline, not a guarantee.' },
    { question: 'How accurate is a race time predictor?', answer: 'Riegel-based predictors are most accurate when the reference and target distances are similar, typically within 2-3 minutes for a well-trained runner. A 10K-to-half-marathon prediction or half-to-marathon prediction is usually within 2-3 minutes. Predicting a marathon from a 5K is less reliable because the two events demand different physiology, and 5K speed does not guarantee marathon endurance. For best accuracy, use your most recent race at a distance as close as possible to the target.' },
    { question: 'What finish time will I get running 6:00/km for a half marathon?', answer: 'Running 6:00 per kilometer for a half marathon (21.0975 km) produces a finish time of 126.6 minutes, which is 2:06:36. Your 5K checkpoints would be 30:00, 1:00:00 at 10K, 1:30:00 at 15K, and 2:00:00 at 20K. That is a very achievable first-half goal for many runners. If you want a sub-2:00 finish instead, you would need to hold 5:41/km, about 19 seconds per kilometer faster.' },
    { question: 'How much can a taper improve my race finish time?', answer: 'A proper taper, reducing volume by 20-40% in the final 2-3 weeks while keeping a little intensity, typically improves performance by 1-3%. In a marathon, that is often 2-5 minutes; in a 5K, about 15-30 seconds. The gains come from fully restored glycogen stores, reduced muscle damage, and fresher legs. Runners who skip the taper and train hard into race week routinely finish 3-5% slower than their fitness allows. Trust the taper and arrive rested.' },
  ],

  'swim-pace-calculator': [
    { question: 'How is swim pace calculated?', answer: 'Swim pace is the time it takes to swim 100 meters or 100 yards. Divide your total time in seconds by the distance, then multiply by 100. If you swim 1,500 meters in 30 minutes (1,800 seconds), that is 1,800 divided by 1,500, times 100 = 120 seconds, or 2:00 per 100m. To get a total race time from a pace, multiply the pace by the number of 100s in the distance. This is the standard unit every swimmer and triathlete uses.' },
    { question: 'What is a good swim pace for a triathlete?', answer: 'For recreational triathletes, a swim pace of 1:45 to 2:15 per 100 meters is common and respectable. Advanced age-group triathletes hold 1:30-1:45, and elite athletes swim under 1:20 per 100m. For triathlon distances, that translates to about 27-34 minutes for a 1,500m Olympic swim at 1:45-2:15 pace. Most new triathletes should target 2:00-2:30/100m and focus on smooth, efficient technique rather than raw speed, since the swim is only a small fraction of total race time.' },
    { question: 'How do I convert swim pace between meters and yards?', answer: 'A 100-meter swim is about 109.4 yards, so 100-yard pace is always a faster number than 100-meter pace at the same effort. Multiply your 100-yard pace in seconds by 1.09361 to get 100-meter pace: 1:30/100y becomes 1:38/100m. Divide by 1.09361 to go the other way. US pools are typically 25 yards while international pools use meters, so always keep the unit consistent with the pool you are swimming in when setting splits.' },
    { question: 'What is a good swim pace for a beginner?', answer: 'Beginners typically swim 2:15 to 2:45 per 100 meters. After 3-6 months of consistent pool work, most recreational swimmers reach around 2:00/100m, and breaking 2:00 is a solid milestone. Swimming is highly technique-dependent, so most early improvement comes from drills and stroke efficiency rather than fitness. A common progression is to practice 25-50m repeats with rest, then build toward continuous 200m and 400m swims at your target pace.' },
    { question: 'How much slower is open water swimming than the pool?', answer: 'Open water swimming is typically 5-10% slower than pool swimming at the same effort. You lose the walls to push off from, must lift your head to sight, deal with waves and currents, and navigate around other swimmers. A 2:00/100m pool pace becomes about 2:06-2:12/100m in open water. Wetsuits add some buoyancy and can partially offset this. Plan your open water or triathlon swim pace with this buffer built in.' },
    { question: 'How do I calculate my Critical Swim Speed (CSS)?', answer: 'Critical Swim Speed estimates your threshold pace and is calculated from two time trials: CSS (seconds per 100m) = (400m time in seconds - 200m time in seconds) divided by 2. If you swim 400m in 7:00 and 200m in 3:20, that is (420 - 200) / 2 = 110 seconds, or 1:50/100m. CSS-based training, researched extensively, improves lactate threshold and swimming economy. Base your aerobic sets 10-15 seconds per 100m slower than CSS and threshold sets right at it.' },
    { question: 'What are the triathlon swim distances?', answer: 'Standard triathlon swim distances are: super-sprint 400m, sprint 750m, Olympic 1,500m, half Ironman (70.3) 1,900m, and Ironman 3,800m. Using pace per 100m, a 2:00/100m swimmer would take about 30 minutes for the Olympic swim, 38 minutes for 70.3, and 76 minutes for Ironman. US yard pools convert these to roughly 1,650, 2,112, and 4,224 yards. Most age-group triathletes swim the first 200m too hard, so start conservatively to avoid an early lactate spike.' },
  ],

  'treadmill-pace-calculator': [
    { question: 'How do I convert treadmill speed to running pace?', answer: 'Divide 60 by the speed in mph or km/h to get your pace in minutes. At 10 km/h, 60 divided by 10 = 6:00 per kilometer. At 6 mph, 60 divided by 6 = 10:00 per mile. The relationship is the same in both units: pace = 60 / speed. This calculator handles both directions, so you can enter an outdoor pace and get the treadmill speed, or enter the machine\'s speed and see your equivalent pace per mile and per kilometer.' },
    { question: 'What incline should I use to simulate running outdoors?', answer: 'Set the treadmill to 1% incline to reproduce the energy cost of running outdoors on flat ground at paces between about 9:11 and 5:22 per mile. This comes from a landmark 1996 study by Jones and Doust. For easy running slower than 9:11/mile, 0.5% is closer to outdoor effort, and for very fast running under 5:22/mile, about 2% matches better. Below these ranges the difference is small enough that 0% is fine for recovery runs.' },
    { question: 'What treadmill speed is a 9:00 mile?', answer: 'A 9:00 mile is 6.7 mph, because 60 minutes divided by 9 = 6.67 mph. In metric, that is about 10.8 km/h, or 5:34 per kilometer. If your treadmill only shows speed in mph, set 6.7; if it shows both, match the mph figure. This is a common easy-to-moderate pace for many recreational runners. The calculator lets you enter 9:00 per mile and instantly shows the matching mph and km/h settings.' },
    { question: 'Is treadmill running easier or harder than running outside?', answer: 'At the same speed on a flat belt, treadmill running is roughly 2-5% easier than outdoor running because there is no air resistance and the belt assists your leg turnover. Heart rate runs about 3-4 beats per minute lower on a flat treadmill. The 1% incline rule compensates for this. However, the lack of airflow can raise core temperature, making long treadmill sessions feel harder mentally. For race pacing, do at least some of your work outdoors.' },
    { question: 'Why does my watch record a different distance on the treadmill?', answer: 'Indoors there is no GPS signal, so your watch estimates distance from arm-swing accelerometer data, which is often 5-15% off and depends on where you wear it. The treadmill\'s belt distance, based on the motor and belt length, is far more accurate for treadmill miles. Many watches pair with the treadmill over ANT+ or Bluetooth to sync the exact belt distance. A footpod is the most accurate option for indoor distance without pairing.' },
    { question: 'How do I convert km/h to min/mile on a treadmill?', answer: 'First convert km/h to minutes per kilometer by dividing 60 by the speed: 12 km/h gives 5:00/km. Then multiply by 1.609 to get minutes per mile: 5:00/km becomes about 8:03/mile. Alternatively, convert the speed to mph first by multiplying km/h by 0.6214: 12 km/h = 7.46 mph, and 60 / 7.46 = 8:02/mile. European treadmills use km/h, while US machines use mph, so this conversion matters when traveling.' },
    { question: 'What incline should I use for treadmill hill workouts?', answer: 'For hill-specific training, most runners use 4-10% incline depending on the goal. Sustained aerobic climbs work well at 4-6%, while short power repeats are commonly done at 6-10%. A 6% incline at easy pace raises effort substantially, so slow your belt speed when you raise the grade. For every 1% of incline, expect a meaningful jump in heart rate and effort. Beginners should build incline gradually and always skip the rails, which reduce the work.' },
  ],

  'run-walk-pace-calculator': [
    { question: 'What is the Jeff Galloway run-walk method?', answer: 'The Galloway run-walk-run method, developed by 1972 US Olympian Jeff Galloway, alternates timed running segments with short, planned walk breaks from the very first minute, rather than walking only when tired. A typical pattern is run 3 minutes, walk 1 minute. Taking the break before fatigue sets in keeps legs fresher, lowers injury risk, and often produces equal or faster finish times than continuous running because you fade less at the end.' },
    { question: 'How is average pace calculated for run-walk intervals?', answer: 'Your average pace is total time of one run-walk cycle divided by total distance covered in that cycle, not a simple average of the two paces. If you run 3 minutes at 6:00/km you cover 500m, and walk 1 minute at 9:00/km you cover 111m: in 4 minutes you travel 611m, an average of about 6:33/km. The calculator does this weighted math and projects your finish time over any race distance.' },
    { question: 'What run-walk ratio should I use?', answer: 'Galloway recommends matching the ratio to your pace. Sub-6:00/km runners: run 4:1. 6:00-7:00/km: 3:1. 7:00-8:00/km: 2:1. 8:00-10:00/km: 1:1. Over 10:00/km: 30 seconds run, 30 seconds walk. Beginners often start at 1:1 or 60 seconds run/30 seconds walk, and stronger runners use 4:1 or 5:1. The key is to take the walk break on schedule, before you feel tired, and keep the ratio consistent throughout.' },
    { question: 'What is the Magic Mile test in the Galloway method?', answer: 'The Magic Mile is a 1-mile time trial run at a comfortably hard effort to gauge your current fitness. Galloway\'s prediction formulas multiply your mile time: half marathon prediction = mile time x 1.2 x 13.1, and marathon prediction = mile time x 1.3 x 26.2. A 10:00 Magic Mile therefore predicts a 2:37 half and a 5:41 marathon. Re-run the Magic Mile every 2-3 weeks to track progress and adjust your run-walk ratio.' },
    { question: 'Is run-walk slower than running continuously?', answer: 'Not necessarily, especially over long distances. Walk breaks preserve glycogen, reduce muscle fatigue, and maintain better form in the final miles, so many runners finish marathons faster with run-walk than they did running continuously and slowing down late. Studies show planned walk breaks reduce fatigue markers, and Galloway reports his athletes averaging faster marathons with the method. The effective pace is typically only 5-15% slower than running-only pace, which fatigue easily cancels out.' },
    { question: 'Can I use run-walk intervals in a 5K or 10K?', answer: 'Yes. For shorter races, use shorter intervals like 2:1 (run 2 minutes, walk 1) or 90 seconds run/30 seconds walk. Run-walk works especially well for beginners, runners returning from injury, and anyone racing in hot conditions where continuous effort builds heat quickly. Pre-plan your intervals with this calculator so you know exactly what run pace you need during the run segments to hit your goal finish time, and stick to the plan from mile one.' },
    { question: 'How do I set up my watch for run-walk intervals?', answer: 'Use your watch\'s interval or run-walk timer so it beeps when it is time to switch. On Garmin, create a workout with repeat segments matching your ratio, such as 3 minutes run followed by 1 minute walk, repeating until you stop the timer. This removes the mental burden of tracking and prevents the common failure of extending run segments and skipping walk breaks. Sync the intervals to match the exact ratio your calculator recommends for your goal pace.' },
  ],

  'training-pace-calculator': [
    { question: 'How do I find my easy, tempo, and threshold training paces?', answer: 'Enter a recent race time, like a 5K or 10K, into the calculator. It estimates your fitness level and outputs ranges for each session: easy runs around 60-75% of max heart rate, threshold at about 80-85%, and VO2max intervals at 90-95%. As a check, easy pace is roughly 60-120 seconds per mile slower than 5K race pace, threshold pace is near your 10K race pace, and interval pace is near or slightly faster than 5K pace.' },
    { question: 'What is the difference between tempo and threshold pace?', answer: 'Threshold pace is the maximum speed you can sustain for about one hour, with lactate production and clearance in balance. Tempo pace is slightly slower, typically 10-15 seconds per kilometer slower than threshold, and can be held continuously for 20-40 minutes. Threshold work improves the lactate-clearance ceiling; tempo work builds durability at a hard but sustainable effort. Many coaches use the terms loosely, but on a plan, tempo runs are longer and slightly easier than threshold sessions.' },
    { question: 'What is the 80/20 rule of training?', answer: 'The 80/20 rule, popularized by researcher Stephen Seiler, says roughly 80% of your weekly running volume should be easy (Zone 1-2) and only 20% hard (Zone 4-5). For a 50-mile week, that is 40 easy miles and 10 hard miles, where hard counts only the working portion of workouts, not warm-ups or recovery jogs. Studies of elite endurance athletes show almost all follow roughly this distribution. It maximizes adaptation while minimizing injury and burnout.' },
    { question: 'What is VDOT and how is it calculated?', answer: 'VDOT is a training-adjusted VO2max score developed by Jack Daniels. It is derived from a race result using Daniels\' tables: a 20:00 5K corresponds to a VDOT of about 52, and a 40:00 10K to roughly 49. Once you have your VDOT, it maps to specific paces for easy, marathon, threshold, interval, and repetition runs that are proportional to your actual fitness. Recalculate after every new race, since VDOT rises as you improve.' },
    { question: 'What is the difference between interval pace and repetition pace?', answer: 'Interval (I) pace targets VO2max and is roughly your 3K-5K race pace, run in efforts of about 3-5 minutes with 60-90 seconds of easy jog recovery. Repetition (R) pace is faster, roughly mile-to-1500m pace, run in short efforts of 200-400m with full recovery. Intervals build your aerobic ceiling; repetitions improve running economy and speed. In a weekly plan, most runners do one interval session plus one threshold session, keeping total hard work at about 20% of mileage.' },
    { question: 'How often should I update my training paces?', answer: 'Recalculate your training paces every 4-6 weeks, or whenever you set a new PR in a race or time trial. As fitness improves, paces derived from an old race time become too easy to trigger adaptation and too slow to match your true zones. Races are the best benchmark; in between, use a 5K time trial on the track. Update after every goal race and at the start of each training block so every session stays in the right zone.' },
    { question: 'Should training paces be based on pace or heart rate?', answer: 'Use both. Pace is excellent on flat routes with normal conditions and easy to hit on the track. Heart rate is better in heat, humidity, hills, and when you are fatigued, because it reflects true effort regardless of external conditions. Many coaches recommend pace targets for quality sessions (tempo, threshold, intervals) and heart rate for easy and long runs. If pace says \'easy\' but heart rate is climbing into Zone 3, slow down and trust the heart rate.' },
  ],

  'grade-adjusted-pace-calculator': [
    { question: 'What is Grade Adjusted Pace (GAP)?', answer: 'Grade Adjusted Pace converts your actual pace on a slope into the equivalent pace you would run on flat ground at the same physiological effort. A 6:30/km on a steep climb and a 4:55/km on a flat road may represent identical aerobic effort, and GAP makes that visible. It is not a prediction of what you would actually run on flat ground; it is an effort-equivalent number for comparing hilly workouts, segments, and training zones fairly.' },
    { question: 'How much does running uphill slow you down?', answer: 'Uphill running is exponentially more costly than flat running. Based on the Minetti model of gradient energy cost, a 4% uphill grade adds roughly 85-90 seconds per kilometer to the effort-equivalent pace, a 6% grade adds about 2:20/km, and a 10% grade adds over 4 minutes per kilometer. A 5% grade adds about 1:50/km. Steeper grades cost disproportionately more than gentle ones, which is why hilly routes require either a big pace slowdown or a much higher heart rate.' },
    { question: 'How does GAP work on Strava and Garmin?', answer: 'Strava and Garmin both display a grade-adjusted figure on activities with elevation data, calculated from each device\'s proprietary gradient-to-effort model. The concept is the same as this calculator: it reports the flat-pace equivalent of your effort on hilly terrain. The models agree closely at moderate gradients of about -6% to +8% but can diverge at steeper angles. Small differences between apps are normal, not errors, so use GAP as a trend indicator rather than a precise measurement.' },
    { question: 'How much does downhill running help your pace?', answer: 'Downhill running saves energy, but far less than the same grade uphill costs, and only up to a point. Using the Minetti model, a -4% descent saves about 60 seconds per kilometer and a -10% descent saves under two minutes, while the same uphills cost two to four times more. On very steep descents, the eccentric braking work your muscles do to control speed becomes expensive again, so extremely steep downhills can be no faster than flat running.' },
    { question: 'What is the Minetti formula used by GAP calculators?', answer: 'GAP calculators use the energy-cost model published by Alberto Minetti in the Journal of Applied Physiology (2002). The formula is cost factor = 1 + 6.2g + 25g^2, where g is the gradient as a decimal. For a 5% grade, g = 0.05, so the factor is 1 + 0.31 + 0.0625 = 1.3725. Your GAP equals your actual pace in seconds divided by this factor: running a climb at 367 s/km (6:07) gives 367 / 1.3725 = 267 s/km, or 4:27/km.' },
    { question: 'Should I train by GAP or actual pace on hilly routes?', answer: 'Use GAP to compare effort across hilly and flat routes and to keep your easy and tempo runs in the correct intensity zone. Use actual pace for race-pace practice, because race courses have real hills. A common approach: on hilly routes, keep easy runs in Zone 2 by heart rate and check GAP afterward; for tempo work on hills, aim for a GAP that matches your flat tempo pace. Both numbers together give the full picture.' },
    { question: 'Why is my GAP faster than my actual pace on downhill sections?', answer: 'GAP converts your actual pace into the flat-ground pace that would produce the same effort. On a downhill, gravity assists you, so you move faster for less energy, which means your effort-equivalent flat pace is faster than your actual clock pace. For example, a 4:30/km actual pace on a -5% descent might show a GAP of 3:50/km. This is expected and useful: it lets you judge whether a fast downhill mile was easy or genuinely hard.' },
  ],

  'zone-2-pace-calculator': [
    { question: 'What is Zone 2 running pace?', answer: 'Zone 2 is a low-intensity, purely aerobic effort where your body primarily burns fat for fuel. It corresponds to roughly 60-70% of maximum heart rate (or 60-70% of heart-rate reserve using the Karvonen formula) and feels conversational, like you could hold a full sentence without breathlessness. Zone 2 should make up about 80% of your weekly training volume, because it builds the aerobic base, capillary density, and fat-oxidation machinery that all faster running depends on.' },
    { question: 'How do I calculate my Zone 2 pace range?', answer: 'Enter your age, resting heart rate, and a recent 5K race time. The calculator estimates your Zone 2 range two ways: by heart rate using the Karvonen formula, and by pace, which is typically about 1.5-2.5 minutes per mile (60-120 seconds per kilometer) slower than your 5K race pace. A 25:00 5K runner would do Zone 2 runs around 6:30-7:00/km. Use heart rate as the primary control and pace as a rough target for flat routes.' },
    { question: 'What is the Karvonen formula for Zone 2 heart rate?', answer: 'The Karvonen formula uses heart-rate reserve, the gap between your resting and maximum heart rate: target HR = resting HR + intensity% x (max HR - resting HR). For a 40-year-old with a resting heart rate of 60, max HR is about 180, so Zone 2 at 60-70% is 60 + 0.6 x 120 = 132 bpm at the low end and 60 + 0.7 x 120 = 144 bpm at the high end. This personalizes zones better than the simple 220-age formula alone.' },
    { question: 'How do I find my maximum heart rate?', answer: 'The simple estimate is 220 minus your age, but it can be off by 10-15 beats for many people. A more accurate field test: warm up for 15 minutes, then run 3-4 minutes hard up a steady hill, check your highest heart rate, jog down, and repeat twice more, using the highest number as your max. A lab or lactate test is the gold standard. Your Zone 2 range, especially with the Karvonen formula, is only as accurate as your max HR.' },
    { question: 'What is the MAF method and how does it relate to Zone 2?', answer: 'The MAF (Maximum Aerobic Function) method, created by Phil Maffetone, sets a single aerobic heart-rate ceiling at 180 minus your age. A 40-year-old would stay at or below 140 bpm for all aerobic training. For most runners this sits right inside or just below Zone 2, making it a simpler alternative to Karvonen calculations. MAF training emphasizes months of base building before any speed work, and beginners or recovering runners adjust the number by minus 5.' },
    { question: 'How long should Zone 2 runs be?', answer: 'Most Zone 2 sessions run 45-90 minutes, and in marathon training the long easy runs extend to 2-3 hours. Duration matters more than distance at this intensity, because the physiological adaptations are time-dependent. If your heart rate starts creeping above the Zone 2 ceiling, slow down or walk to bring it back. Beginners can start with 20-30 minutes and build gradually, since staying in Zone 2 while running long requires a developed aerobic system.' },
    { question: 'How do I know I am actually in Zone 2?', answer: 'The talk test is the simplest check: you should be able to speak in complete sentences without gasping, or breathe comfortably through your nose. More precisely, your heart rate should sit in your calculated Zone 2 range, roughly 60-70% of max HR. If you are breathing too hard to talk, you have drifted into Zone 3. Most recreational runners run their easy days too fast, so slowing down until it feels almost embarrassingly easy is usually the correct adjustment.' },
  ],

  'tempo-pace-calculator': [
    { question: 'What is a tempo run pace?', answer: 'Tempo pace is a \'comfortably hard\' effort, around RPE 6-7 out of 10, that you could sustain for about 40-60 minutes in a race. For most runners it lands right around half marathon race pace, roughly 85% of max heart rate. It is typically 25-30 seconds per mile slower than your 5K race pace. At tempo pace you can say a short phrase but not hold a conversation. The goal is to train your body to clear lactate at a faster speed.' },
    { question: 'How long should a tempo run be?', answer: 'A classic tempo run is 20-40 minutes at tempo pace, bookended by a 10-minute warm-up and 10-minute cool-down. Beginners should start with 20 minutes and build to 30-35 over a training block. Beyond 40 minutes you are usually dropping to marathon pace rather than true tempo effort. Advanced runners can break it into intervals, such as 2-3 x 15 minutes at tempo pace with 2-5 minutes easy jog between blocks, accumulating more total tempo time with better quality.' },
    { question: 'How is tempo pace related to half marathon pace?', answer: 'For most runners, tempo pace and half marathon race pace are nearly identical, within about 5-10 seconds per kilometer. That is why tempo runs are such good half marathon preparation: they train your body to sustain the exact effort a sub-2:00 or sub-1:45 half demands. A runner targeting a 5:41/km half (2:00 finish) would do tempo runs at roughly 5:35-5:45/km. Tempo pace is slightly slower than threshold pace and slightly faster than marathon pace.' },
    { question: 'How do I find my tempo pace without a calculator?', answer: 'Run a 30-minute time trial on a flat course after a 10-15 minute warm-up, then use the average pace of the final 20 minutes as your approximate tempo pace. Alternatively, use your 10K race pace, which is very close to tempo pace for many runners, or add about 25-30 seconds per mile to your 5K race pace. Because effort matters more than exact numbers, aim for \'comfortably hard\': working steadily but never gasping.' },
    { question: 'Should I pace tempo runs by pace or by effort?', answer: 'Use effort as the primary guide and pace as a target. On a flat track or road in good weather, your prescribed tempo pace is reliable. In heat, hills, or wind, hold the same RPE 6-7 effort and let the pace fall where it falls, which may be 10-30 seconds per mile slower. Heart rate is a useful middle ground: most runners sit at about 85% of max HR at tempo effort. Never force the pace number on a bad day.' },
    { question: 'What is a tempo interval workout?', answer: 'A tempo interval session breaks the tempo effort into repeat blocks with short recovery, allowing more total time at tempo pace. Examples: 3 x 10 minutes at tempo pace with 2-3 minutes easy jog between, or 2 x 20 minutes with 5 minutes easy. Cruise intervals, like 4 x 1 mile at tempo pace with 60-second jog recovery, are a popular variant. These sessions suit faster runners and still target the lactate-clearance system while reducing the monotony of one long block.' },
    { question: 'How is tempo pace different from marathon pace?', answer: 'Tempo pace is faster than marathon pace, roughly 10-20 seconds per kilometer faster for most runners, because a marathon is run comfortably below threshold while a tempo run sits right at the edge of it. Marathon pace work builds race-specific economy and confidence; tempo work raises your lactate threshold. A 3:30 marathoner (4:58/km) would do tempo runs around 4:40-4:50/km. Both belong in a balanced plan, but they are not interchangeable sessions.' },
  ],

  'threshold-pace-calculator': [
    { question: 'What is lactate threshold pace?', answer: 'Lactate threshold pace is the speed at which lactate begins to accumulate in your blood faster than your body can clear it. In practical terms it is roughly the fastest pace you can sustain for about one hour, and for many runners it falls between 10K and 15K race pace. Effort is \'comfortably hard\', around RPE 7-8 out of 10, at about 85-92% of max heart rate. You can speak in short phrases but not full sentences.' },
    { question: 'How is threshold pace calculated?', answer: 'This calculator estimates threshold pace from a recent race result, most often a 10K, which is run very close to threshold. As a cross-check, your threshold pace is roughly your 10K race pace, or about 10-15 seconds per kilometer faster than half marathon pace. The most accurate field method is a 30-minute all-out time trial, where your average pace and heart rate over the final 20 minutes define your threshold. Retest every 4-6 weeks as fitness improves.' },
    { question: 'How do I test my lactate threshold pace?', answer: 'Warm up for 10-15 minutes easy, then run a hard, even-paced 30-minute time trial. Your average pace over the final 20 minutes is your threshold pace, and your average heart rate over those 20 minutes is your threshold heart rate. Most runners hit roughly 85-92% of max HR. A lab test measuring blood lactate is the gold standard but unnecessary for training. Use the result to set threshold workouts and to calibrate your training zones.' },
    { question: 'How does threshold pace compare to 10K race pace?', answer: 'For most well-trained runners, threshold pace and 10K race pace are nearly identical, within a few seconds per kilometer. That is why a recent 10K time is the best single input for calculating threshold pace. Threshold pace is about 10-15 seconds per kilometer faster than half marathon pace and roughly 20-30 seconds per kilometer slower than 5K race pace. Because a 10K is run at or just above the threshold, don\'t confuse threshold with 5K effort, which is clearly harder.' },
    { question: 'What heart rate corresponds to lactate threshold?', answer: 'Lactate threshold heart rate typically falls between 85-92% of maximum heart rate for most runners. A more precise estimate comes from the 30-minute time-trial protocol: your average heart rate in the final 20 minutes is your threshold heart rate. Many watches call this the LTHR and use it to set zones. At threshold effort you should be able to manage short phrases; if you can\'t speak, you have drifted above the threshold into 5K-to-10K race effort.' },
    { question: 'What are cruise intervals?', answer: 'Cruise intervals are repeated threshold-effort efforts with brief recoveries, developed by Jack Daniels. A classic session is 4-6 x 1 mile at threshold pace with 60 seconds of easy jogging between each, or 3-4 x 8 minutes at threshold with 90 seconds recovery. They let you accumulate more total time at threshold than a single continuous block, with better form and quality. Cruise intervals are a staple for 10K and half marathon training.' },
    { question: 'How much does improving threshold pace improve race times?', answer: 'Threshold pace is the single best predictor of 10K and half marathon performance, because those races are run at or near it. Raising threshold pace by 10 seconds per kilometer can improve a 10K by roughly 1-2 minutes and a half marathon by 2-4 minutes. Since threshold is trainable, one dedicated threshold session per week, about 10% of your weekly volume, produces steady gains. Runners who only run easy or only run hard rarely move the number as fast.' },
  ],

  'easy-run-pace-calculator': [
    { question: 'How slow should my easy run pace be?', answer: 'Your easy run pace should be roughly 60-120 seconds per mile (about 40-75 seconds per kilometer) slower than your current 5K race pace. Newer runners need the bigger gap, 90-120 seconds per mile, because their aerobic base is still developing. If you cannot hold a full conversation, you are running too fast. Easy runs feel deceptively slow, and that is the point: the effort keeps your heart rate low enough that recovery happens while you train.' },
    { question: 'Will running too slow hurt my race fitness?', answer: 'No. Research shows that easy running between 55-75% of 5K race pace produces near-identical aerobic adaptations at the slow end as at the fast end, while leaving you better recovered. Capillary density, mitochondrial growth, and glycogen storage all develop at easy effort. Running too fast is the bigger risk: it adds fatigue without extra benefit. Most elite training includes the vast majority of miles at genuinely easy pace, so slow running is a feature, not a flaw.' },
    { question: 'What heart rate should an easy run stay below?', answer: 'Easy runs should stay in Zone 1-2, roughly 60-75% of maximum heart rate, which corresponds to about 65-78% of max in some zone systems. Many coaches cap easy runs below 75% of max HR. A 40-year-old with an estimated max of 180 bpm would keep easy runs at about 108-135 bpm. If your heart rate creeps above the ceiling, slow down or walk until it drops. Heart rate beats pace on hot, hilly, or fatigued days.' },
    { question: 'What happens if I run all my easy runs too fast?', answer: 'Running easy days too fast is the most common training mistake. It turns recovery miles into moderate-effort work, accumulating fatigue without adding meaningful fitness. The result is chronic tiredness, worsening workout quality, higher injury risk, and the \'moderate-intensity rut\' where you are never easy enough to recover or hard enough to adapt. The fix is uncomfortable: slow down 30-60 seconds per mile and watch your easy pace sit genuinely below threshold.' },
    { question: 'How long should easy runs be?', answer: 'Easy runs typically last 30-90 minutes depending on your weekly mileage and goal. Beginners can start at 20-30 minutes and build gradually. The weekly long run is the extended easy session, stretching to 2-3 hours in marathon training. Duration at easy effort is what builds aerobic endurance, so keep the pace slow enough that longer runs feel sustainable. Short easy runs between hard sessions support recovery, while the long easy run drives base fitness.' },
    { question: 'Should I take walk breaks on easy runs?', answer: 'Yes, whenever needed. Walk breaks keep your heart rate in Zone 2 and let beginners and returning runners accumulate time on feet without excess stress. Walking in Zone 2 still builds the aerobic base, with far less joint impact than running. As fitness improves you will naturally need fewer breaks. Many coaches encourage walk breaks on easy and long runs for beginners, and planned run-walk intervals are a legitimate strategy for marathoners as well.' },
    { question: 'How do I know if my easy pace is actually easy?', answer: 'Use the talk test plus heart rate. You should be able to speak in complete sentences without gasping; if you can sing, you may be slightly under, which is fine. Your heart rate should sit below about 75% of max. If you dread easy runs because they feel hard, your pace is too fast. A useful check: easy runs should leave you feeling better, not worse, and you should look forward to the next session rather than needing multiple days to recover.' },
  ],

  'long-run-pace-calculator': [
    { question: 'What is a good pace for a weekly long run?', answer: 'Your weekly long run should be 10-20% slower than your goal race pace, or about 45-100 seconds per kilometer slower. If your marathon pace is 5:00/km, long runs belong around 5:30-6:00/km. The primary goal is time on feet and aerobic endurance, not speed. Research points to 55-75% of 5K race pace as the optimal effort band, with the average target near 65%. Long runs should feel comfortable and conversational from start to finish.' },
    { question: 'How long should my longest long run be before a marathon?', answer: 'Most marathon plans peak the long run at 20-22 miles (32-35 km). Going beyond 22 miles raises injury risk without meaningful additional aerobic benefit, because the endurance adaptations plateau around 2.5-3 hours of running regardless of distance. Hal Higdon\'s plans top out at 20 miles, while Pfitzinger programs reach 20-22. Beginners can safely peak at 18-20 miles. Run the last few miles at marathon pace if the plan calls for it, then taper.' },
    { question: 'How much slower than marathon pace should long runs be?', answer: 'Use a 10-20% slowdown from marathon goal pace, a guideline from Pete Pfitzinger echoed by Runner\'s World. At 9:00/mile marathon pace, that is long runs of 9:54-10:48/mile. Runner\'s World\'s intensity recommendation sits in the same band. The first few miles should be the slowest, nearly jogging, then settle in. Faster long runs belong only in structured workouts, like the final 5-8 miles at marathon pace, not for the entire run.' },
    { question: 'How often should I do long runs?', answer: 'Do one long run per week, typically on a weekend when you have time. Every 3-4 weeks, cut the long run back by 20-30% for a recovery week, which lets your body absorb the training stimulus and prevents overuse injuries. Long runs build progressively, usually adding no more than 10% of distance per week. In a 16-20 week marathon block, long runs build from about 10 miles to a peak of 20-22 miles before tapering.' },
    { question: 'What is a progression long run?', answer: 'A progression long run starts well below goal pace and gradually accelerates, finishing at or slightly above marathon goal pace. For example, start the first 2-3 miles at 60-90 seconds per mile slower than marathon pace, settle to easy pace, then run the final 20-30 minutes at marathon pace. This teaches your body to run fast on tired legs, mimicking the final 10K of a marathon, and builds the mental confidence to accelerate late. Do them only in the back half of a training block.' },
    { question: 'How fast should the first mile of a long run feel?', answer: 'The first mile of a long run should feel almost painfully slow, like an easy jog or shuffle. Most coaches recommend taking the opening 1-2 miles as a warm-up, 60-120 seconds per mile slower than your average long-run pace, then gradually settling in. This conserves glycogen, warms up the muscles and cardiovascular system, and ensures the middle of the run is not slower than the start. Many runners make the mistake of starting at target pace and fading.' },
    { question: 'Should I fuel during long runs?', answer: 'Yes, for runs longer than 75-90 minutes. Practice taking in 30-60g of carbohydrates per hour, from gels, chews, or sports drink, starting before you feel depleted rather than after. This trains your gut to absorb fuel during the marathon and prevents glycogen depletion in the final miles. For runs over 2.5 hours, aim for the upper end, 60-90g per hour. Always rehearse your exact race-day fueling plan in training, never experiment on race day.' },
  ],

};

export const defaultFaqs: FAQItem[] = [
  { question: 'Is this calculator free?', answer: 'Yes. It works without an account, subscription or usage limit.' },
  { question: 'Does CalcFino store my result?', answer: 'No. Calculations run in your browser and the entered training data is not sent to CalcFino.' },
  { question: 'Why might my watch show a different pace?', answer: 'A watch may use moving time, auto-pause, smoothed current pace or a GPS-measured distance. This tool uses the exact values you enter.' },
  { question: 'Should I follow the result exactly?', answer: 'No. Use it as a baseline and account for weather, terrain, recovery, experience and health.' }
];

export function getRunningFaqs(slug: string): FAQItem[] {
  return runningFaqs[slug] || defaultFaqs;
}
